import React from 'react';
import { BrowserRouter as Router, Route, Routes } from 'react-router-dom';
import { AuthProvider } from './context/AuthContext'; // Make sure AuthContext is imported
import ProtectedRoute from './components/ProtectedRoute';
import Login from './components/Auth/'; // Assuming Login component is directly importable
import Register from './components/Register'; // Import the new Register component
import Navbar from './components/Navbar'; // Import the Navbar component

import HomePage from './pages/HomePage';
import LoginPage from './pages/LoginPage';
import RegisterPage from './pages/RegisterPage';
import UserDashboard from './components/UserDashboard'; // Keep using components directly or as part of pages
import AdminDashboard from './components/AdminDashboard'; // Keep using components directly or as part of pages
import UnauthorizedPage from './pages/UnauthorizedPage';
import NotFoundPage from './pages/NotFoundPage';

function App() {
  return (
    <Router>
      <Navbar /> {/* Navbar shown on all pages */}
      <div className="container mx-auto mt-4 px-4"> {/* Add a container for content */}
        <Routes>
          {/* Public Routes */}
          <Route path="/" element={<HomePage />} />
          <Route path="/login" element={<LoginPage />} />
          <Route path="/register" element={<RegisterPage />} />

          {/* Protected Routes */}
          <Route
            path="/dashboard"
            element={
              <ProtectedRoute>
                {/* This could dynamically show UserDashboard or AdminDashboard,
                    or you can have separate routes for them.
                    For simplicity, we'll assume a general dashboard view
                    that might internally check role, or separate routes.
                    Let's make separate routes for clarity of RBAC. */}
                <UserDashboard />
              </ProtectedRoute>
            }
          />
          <Route
            path="/admin"
            element={
              <ProtectedRoute adminOnly={true}>
                <AdminDashboard />
              </ProtectedRoute>
            }
          />

          {/* Specific User Dashboard Route */}
          <Route
            path="/user/dashboard"
            element={
              <ProtectedRoute>
                <UserDashboard />
              </ProtectedRoute>
            }
          />

          {/* Specific Admin Dashboard Route */}
          <Route
            path="/admin/dashboard"
            element={
              <ProtectedRoute adminOnly={true}>
                <AdminDashboard />
              </ProtectedRoute>
            }
          />


          {/* Access Denied Route */}
          <Route path="/unauthorized" element={<UnauthorizedPage />} />

          {/* 404 Not Found Route */}
          <Route path="*" element={<NotFoundPage />} />
        </Routes>
      </div>
    </Router>
  );
}

export default App;
